59	    <div class="container">
60	        <h1>Claude Code Trace Visualizer</h1>
61	        <div class="controls">
62	            <select id="projectSelect"><option>Loading projects...</option></select>
63	            <select id="sessionSelect"><option>Select a project first</option></select>
64	            <button onclick="loadSession()">Load</button>
65	            <button onclick="toggleAll(true)">Expand All</button>
66	            <button onclick="toggleAll(false)">Collapse All</button>
67	        </div>
68	        <div id="sessionInfo" class="session-info" style="display:none;"></div>
69	        <div id="messages" class="loading">Select a project and session to view traces</div>
70	    </div>
71	    <script>
72	        let sessions = {}, currentMessages = [];
73	        
74	        async function init() {
75	            const index = await (await fetch('/api/index')).json();
76	            const projectSelect = document.getElementById('projectSelect');
77	            projectSelect.innerHTML = '<option value="">Select project...</option>' + 
78	                Object.keys(index).map(p => `<option value="${p}">${p.split('/').pop()}</option>`).join('');
79	            sessions = index;
80	            projectSelect.onchange = () => {
81	                const sessionSelect = document.getElementById('sessionSelect');
82	                const project = projectSelect.value;
83	                sessionSelect.innerHTML = project ? 
84	                    sessions[project].map(s => `<option value="${s.file}">${s.session_id} (${new Date(s.timestamp).toLocaleString()}) - ${s.message_count} msgs</option>`).join('') :
85	                    '<option>Select a project first</option>';
86	            };
87	        }
88	        
89	        async function loadSession() {
90	            const file = document.getElementById('sessionSelect').value;
91	            if (!file) return;
92	            document.getElementById('messages').innerHTML = '<div class="loading">Loading...</div>';
93	            const data = await (await fetch(`/api/session?file=${encodeURIComponent(file)}`)).json();
94	            currentMessages = data;
95	            renderMessages(data);
96	        }
97	        
98	        function getPreview(msg) {
99	            if (!msg.message?.content) return '';
100	            const content = msg.message.content;
101	            if (typeof content === 'string') return content.slice(0, 100);
102	            for (const block of content) {
103	                if (block.type === 'text') return block.text?.slice(0, 100) || '';
104	                if (block.type === 'tool_use') return `Tool: ${block.name}`;
105	                if (block.type === 'tool_result') return `Result for: ${block.tool_use_id?.slice(-8) || 'unknown'}`;
106	            }
107	            return '';
108	        }
109	        
110	        function formatStandardTool(block) {
111	            const name = block.name;
112	            const input = block.input || {};
113	            
114	            // Bash tool
115	            if (name === 'Bash') {
116	                return `<div class="std-tool">
117	                    <div class="std-tool-header">$ Bash</div>
118	                    <div class="std-tool-content">
119	                        <div class="std-tool-label">Command:</div>
120	                        <pre>${escapeHtml(input.command || '')}</pre>
121	                        ${input.timeout ? `<div class="std-tool-label" style="margin-top:8px">Timeout: ${input.timeout}ms</div>` : ''}
122	                    </div>
123	                </div>`;
124	            }
125	            
126	            // Read tool
127	            if (name === 'Read') {
128	                return `<div class="std-tool">
129	                    <div class="std-tool-header">Read File</div>
130	                    <div class="std-tool-content">
131	                        <pre>${escapeHtml(input.file_path || '')}</pre>
132	                        ${input.offset !== undefined ? `<div class="std-tool-label" style="margin-top:8px">Offset: ${input.offset}, Limit: ${input.limit || 'none'}</div>` : ''}
133	                    </div>
134	                </div>`;
135	            }
136	            
137	            // Write tool
138	            if (name === 'Write') {
139	                return `<div class="std-tool">
140	                    <div class="std-tool-header">Write File</div>
141	                    <div class="std-tool-content">
142	                        <div class="std-tool-label">Path:</div>
143	                        <pre>${escapeHtml(input.file_path || '')}</pre>
144	                        <div class="std-tool-label" style="margin-top:8px">Content:</div>
145	                        <pre>${escapeHtml(input.content || '')}</pre>
146	                    </div>
147	                </div>`;
148	            }
149	            
150	            // Edit tool
151	            if (name === 'Edit') {
152	                return `<div class="std-tool">
153	                    <div class="std-tool-header">Edit File</div>
154	                    <div class="std-tool-content">
155	                        <div class="std-tool-label">Path:</div>
156	                        <pre>${escapeHtml(input.file_path || '')}</pre>
157	                        <div class="std-tool-label" style="margin-top:8px">Old:</div>
158	                        <pre style="background:#2d1f1f;padding:8px;border-radius:4px">${escapeHtml(input.old_string || '')}</pre>
159	                        <div class="std-tool-label" style="margin-top:8px">New:</div>
160	                        <pre style="background:#1f2d1f;padding:8px;border-radius:4px">${escapeHtml(input.new_string || '')}</pre>
161	                    </div>
162	                </div>`;
163	            }
164	            
165	            // Glob tool
166	            if (name === 'Glob') {
167	                return `<div class="std-tool">
168	                    <div class="std-tool-header">Glob Search</div>
169	                    <div class="std-tool-content">
170	                        <div class="std-tool-label">Pattern:</div>
171	                        <pre>${escapeHtml(input.pattern || '')}</pre>
172	                        ${input.path ? `<div class="std-tool-label" style="margin-top:8px">Path: ${escapeHtml(input.path)}</div>` : ''}
173	                    </div>
174	                </div>`;
175	            }
176	            
177	            // Grep tool
178	            if (name === 'Grep') {
179	                return `<div class="std-tool">
180	                    <div class="std-tool-header">Grep Search</div>
181	                    <div class="std-tool-content">
182	                        <div class="std-tool-label">Pattern:</div>
183	                        <pre>${escapeHtml(input.pattern || '')}</pre>
184	                        ${input.path ? `<div class="std-tool-label" style="margin-top:8px">Path: ${escapeHtml(input.path)}</div>` : ''}
185	                        ${input.include ? `<div class="std-tool-label" style="margin-top:8px">Include: ${escapeHtml(input.include)}</div>` : ''}
186	                    </div>
187	                </div>`;
188	            }
189	            
190	            // LS tool (if exists)
191	            if (name === 'LS' || name === 'ListDirectory') {
192	                return `<div class="std-tool">
193	                    <div class="std-tool-header">List Directory</div>
194	                    <div class="std-tool-content">
195	                        <pre>${escapeHtml(input.path || input.directory || '.')}</pre>
196	                    </div>
197	                </div>`;
198	            }
199	            
200	            // Default: return null to use generic rendering
201	            return null;
202	        }
203	        
204	        function escapeHtml(text) {
205	            if (typeof text !== 'string') text = JSON.stringify(text, null, 2);
206	            return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
207	        }
208	        
209	        function renderBlock(block) {
210	            if (block.type === 'text') {
211	                return `<div class="content-block"><div class="block-type">Text</div><div class="text-content">${escapeHtml(block.text || '')}</div></div>`;
212	            }
213	            if (block.type === 'tool_use') {
214	                const standardRender = formatStandardTool(block);
215	                if (standardRender) {
216	                    return `<div class="content-block">${standardRender}</div>`;
217	                }
218	                return `<div class="content-block tool-use"><div class="block-type">Tool Use</div><div><span class="tool-name">${escapeHtml(block.name || 'unknown')}</span> <span class="meta">(${block.id || 'no-id'})</span></div><div class="tool-input">${escapeHtml(JSON.stringify(block.input || {}, null, 2))}</div></div>`;
219	            }
220	            if (block.type === 'tool_result') {
221	                const isError = block.is_error;
222	                let content = block.content;
223	                if (Array.isArray(content)) content = content.map(c => c.text || JSON.stringify(c)).join('\n');
224	                return `<div class="content-block"><div class="block-type">Tool Result ${isError ? '(Error)' : ''}</div><div class="tool-result ${isError ? 'error' : ''}">${escapeHtml(content || '')}</div></div>`;
225	            }
226	            return `<div class="content-block"><div class="block-type">${block.type || 'unknown'}</div><pre>${escapeHtml(JSON.stringify(block, null, 2))}</pre></div>`;
227	        }
228	        
229	        function renderMessages(messages) {
230	            const container = document.getElementById('messages');
231	            if (!messages.length) { container.innerHTML = '<div class="empty">No messages in this session</div>'; return; }
232	            
233	            const sessionInfo = document.getElementById('sessionInfo');
234	            const first = messages[0], last = messages[messages.length - 1];
235	            sessionInfo.style.display = 'block';
236	            sessionInfo.innerHTML = `<span>Messages: <strong>${messages.length}</strong></span>
237	                <span>Start: <strong>${new Date(first.timestamp).toLocaleString()}</strong></span>
238	                <span>End: <strong>${new Date(last.timestamp).toLocaleString()}</strong></span>`;
239	            
240	            container.innerHTML = messages.map((msg, i) => {
241	                const role = msg.message?.role || msg.type || 'unknown';
242	                const content = msg.message?.content;
243	                const cacheRead = msg.message?.cache_read;
244	                const cacheWrite = msg.message?.cache_creation_input_tokens;
245	                let cacheHtml = '';
246	                if (cacheRead) cacheHtml = '<span class="cache-status hit">Cache Hit</span>';
247	                else if (cacheWrite) cacheHtml = '<span class="cache-status write">Cache Write</span>';
248	                
249	                let blocksHtml = '';
250	                if (typeof content === 'string') {
251	                    blocksHtml = `<div class="content-block"><div class="text-content">${escapeHtml(content)}</div></div>`;
252	                } else if (Array.isArray(content)) {
253	                    blocksHtml = content.map(renderBlock).join('');
254	                }
255	                
256	                return `<div class="message ${role}" onclick="this.classList.toggle('expanded')">
257	                    <div class="message-header">
258	                        <span class="role">${role}${cacheHtml}</span>
259	                        <span class="preview">${escapeHtml(getPreview(msg))}</span>
260	                        <span class="toggle">▼</span>
261	                    </div>
262	                    <div class="message-content" onclick="event.stopPropagation()">${blocksHtml}</div>
263	                </div>`;
264	            }).join('');
265	        }
266	        
267	        function toggleAll(expand) {
268	            document.querySelectorAll('.message').forEach(m => m.classList.toggle('expanded', expand));
269	        }
270	        
271	        init();
272	    </script>
