1	from http.server import HTTPServer, SimpleHTTPRequestHandler
2	import json
3	import urllib.parse
4	
5	class Handler(SimpleHTTPRequestHandler):
6	    def do_GET(self):
7	        parsed = urllib.parse.urlparse(self.path)
8	        
9	        if parsed.path == '/api/index':
10	            self.send_response(200)
11	            self.send_header('Content-type', 'application/json')
12	            self.end_headers()
13	            with open('data/index.json') as f:
14	                self.wfile.write(f.read().encode())
15	            return
16	            
17	        if parsed.path == '/api/session':
18	            params = urllib.parse.parse_qs(parsed.query)
19	            file_path = params.get('file', [''])[0]
20	            if file_path:
21	                self.send_response(200)
22	                self.send_header('Content-type', 'application/json')
23	                self.end_headers()
24	                messages = []
25	                with open(file_path) as f:
26	                    for line in f:
27	                        if line.strip():
28	                            messages.append(json.loads(line))
29	                self.wfile.write(json.dumps(messages).encode())
30	                return
31	        
32	        return super().do_GET()
33	
34	if __name__ == '__main__':
35	    server = HTTPServer(('', 44043), Handler)
36	    print('Server running at http://localhost:44043/')
37	    server.serve_forever()
</response>

