1	#!/usr/bin/env python3
2	import json
3	from pathlib import Path
4	
5	def build_index():
6	    data_dir = Path("data/projects")
7	    index = {}
8	    
9	    for project_dir in data_dir.iterdir():
10	        if not project_dir.is_dir():
11	            continue
12	            
13	        project_name = project_dir.name.replace('-', '/')
14	        sessions = []
15	        
16	        for jsonl_file in project_dir.glob("*.jsonl"):
17	            # Read first line to get session info
18	            with open(jsonl_file) as f:
19	                first_line = f.readline()
20	                if first_line:
21	                    first_msg = json.loads(first_line)
22	                    # Count total messages
23	                    f.seek(0)
24	                    msg_count = sum(1 for line in f if line.strip())
25	                    
26	                    sessions.append({
27	                        "file": str(jsonl_file),
28	                        "session_id": first_msg.get("session_id", jsonl_file.stem),
29	                        "timestamp": first_msg.get("timestamp", ""),
30	                        "message_count": msg_count
31	                    })
32	        
33	        if sessions:
34	            # Sort by timestamp descending
35	            sessions.sort(key=lambda x: x["timestamp"], reverse=True)
36	            index[project_name] = sessions
37	    
38	    with open("data/index.json", "w") as f:
39	        json.dump(index, f, indent=2)
40	    
41	    print(f"Built index with {len(index)} projects")
42	
43	if __name__ == "__main__":
44	    build_index()
</response>

